#[rustc_nounwind]
pub const unsafe fn simd_with_exposed_provenance<T, U>(addr: T) -> U;

/// Swaps bytes of each element.
///
/// `T` must be a vector of integers.
#[rustc_intrinsic]
#[rustc_nounwind]
pub const unsafe fn simd_bswap<T>(x: T) -> T;

