    #[stable(feature = "rust1", since = "1.0.0")]
    #[rustc_non_const_trait_method]
    fn skip(self, n: usize) -> Skip<Self>
    where
        Self: Sized,
    {
        Skip::new(self, n)
    }

    /// Creates an iterator that yields the first `n` elements, or fewer
