    #[inline]
    #[stable(feature = "rust1", since = "1.0.0")]
    #[rustc_non_const_trait_method]
    fn take(self, n: usize) -> Take<Self>
    where
        Self: Sized,
    {
        Take::new(self, n)
    }

    /// An iterator adapter which, like [`fold`], holds internal state, but
