    #[rustc_const_stable(feature = "const_float_methods", since = "1.85.0")]
    #[inline]
    pub const fn min(self, other: f32) -> f32 {
        intrinsics::minimum_number_nsz_f32(self, other)
    }

    /// Returns the maximum of the two numbers, propagating NaN.
