        #[doc = concat!("pub fn carryless_mul(lhs: ", stringify!($SelfT), ", rhs: ", stringify!($SelfT), ") -> ", stringify!($SelfT), "{")]
        ///     let mut retval = 0;
        #[doc = concat!("    for i in 0..",  stringify!($SelfT), "::BITS {")]
        ///         if (rhs >> i) & 1 != 0 {
        ///             // long multiplication would use +=
        ///             retval ^= lhs << i;
        ///         }
