    any(
        all(target_os = "windows", not(target_vendor = "win7")),
        target_os = "linux",
        target_os = "android",
        all(target_family = "wasm", target_feature = "atomics"),
        target_os = "freebsd",
        target_os = "openbsd",
        target_os = "dragonfly",
        target_os = "fuchsia",
        target_os = "motor",
        target_os = "hermit",
    ) => {
        mod futex;
        pub use futex::Parker;
    }
    any(
        target_os = "netbsd",
        all(target_vendor = "fortanix", target_env = "sgx"),
        target_os = "solid_asp3",
    ) => {
        mod id;
        pub use id::Parker;
    }
    target_vendor = "win7" => {
